import { ArrowUpRight } from 'lucide-react';

export default function CountryCard({ code, name, focus, featured = false, onClick, clickable = false }) {
  const Component = onClick ? 'button' : 'article';

  return (
    <Component
      type={onClick ? 'button' : undefined}
      className={`country-card ${featured ? 'country-card-featured' : ''}`}
      onClick={onClick}
      aria-label={clickable ? `${name} country page` : undefined}
    >
      <span className="country-code" aria-hidden="true">{code}</span>
      <div className="country-card-copy">
        <h3>{name}</h3>
        <p>{focus}</p>
      </div>
      <ArrowUpRight aria-hidden="true" />
    </Component>
  );
}
